t=one(t,'  const[internalConsumption,setInternalConsumption]=useState(false);\n  const[dragCategory,setDragCategory]=useState("");','  const[internalConsumption,setInternalConsumption]=useState(false);\n  const[categoryOrderMode,setCategoryOrderMode]=useState(false);\n  const[dragCategory,setDragCategory]=useState("");','pos order mode state')
