newcat='<div className="category-toolbar"><div className="category-strip">{categories.map(item=><button key={item} draggable={!categoryOrderMode&&item!=="Todos"} className={`${category===item?"selected":""} ${dragCategory===item?"category-dragging":""} ${dragOverCategory===item?"category-drop-target":""}`} onClick={()=>setCategory(item)} onDragStart={event=>{if(!categoryOrderMode&&item!=="Todos"){event.dataTransfer.effectAllowed="move";event.dataTransfer.setData("text/plain",item);setDragCategory(item)}}} onDragEnter={()=>{if(!categoryOrderMode&&item!=="Todos"&&dragCategory&&dragCategory!==item)setDragOverCategory(item)}} onDragOver={event=>{if(!categoryOrderMode&&item!=="Todos"){event.preventDefault();event.dataTransfer.dropEffect="move";setDragOverCategory(item)}}} onDrop={event=>{event.preventDefault();const source=event.dataTransfer.getData("text/plain")||dragCategory;moveCategory(source,item)}} onDragEnd={()=>{setDragCategory("");setDragOverCategory("")}}>{item}</button>)}</div>{orderedCategories.length>1&&<button type="button" className={`category-order-toggle ${categoryOrderMode?"active":""}`} onClick={()=>setCategoryOrderMode(value=>!value)}>{categoryOrderMode?"✓ Listo":"↕ Ordenar"}</button>}</div>{categoryOrderMode&&<div className="category-order-editor" aria-label="Ordenar categorías">{orderedCategories.map((item,index)=><div className="category-order-item" key={item}><button type="button" className="category-order-label" onClick={()=>setCategory(item)}>{index+1}. {item}</button><span><button type="button" aria-label={`Mover ${item} a la izquierda`} disabled={index===0} onClick={()=>shiftCategory(item,-1)}>←</button><button type="button" aria-label={`Mover ${item} a la derecha`} disabled={index===orderedCategories.length-1} onClick={()=>shiftCategory(item,1)}>→</button></span></div>)}</div>}'
