# Inventory: editing a controlled item now includes stock, cost, unit and alert threshold in one workflow.
p=Path('components/InventoryClient.tsx');t=p.read_text()
pattern=r'  const updateIngredient=\(e:FormEvent<HTMLFormElement>,productId:string\)=>\{.*?\};\n  const addRecipeComponent='
replacement='''  const updateIngredient=(e:FormEvent<HTMLFormElement>,productId:string)=>{
    e.preventDefault();const f=new FormData(e.currentTarget),name=clean(String(f.get("name")||"")),unit=clean(String(f.get("unit")||"u"))||"u",cost=Number(f.get("cost")||0),threshold=Number(f.get("threshold")||0),stock=Number(f.get("stock")||0),stockReason=clean(String(f.get("stockReason")||""));
    if(!name||!Number.isFinite(cost)||cost<0||!Number.isFinite(threshold)||threshold<0||!Number.isFinite(stock)||stock<0){setMessage("Revisa los datos del ingrediente");return}
    if(isYuki&&(!Number.isInteger(threshold)||!Number.isInteger(stock))){setMessage("En YUKI el stock y el mínimo deben ser unidades completas");return}
    const next=loadLocalDatabase(),workspace=getWorkspaceContext(next),product=next.tenantProducts.find(p=>p.id===productId&&p.tenantId===workspace.tenantId&&p.branchId===workspace.branchId&&inventoryOnly(p));if(!product){setMessage("Ingrediente no encontrado");return}
    const duplicate=next.tenantProducts.find(p=>p.id!==productId&&p.tenantId===workspace.tenantId&&p.branchId===workspace.branchId&&inventoryOnly(p)&&p.name.toLocaleLowerCase("es")===name.toLocaleLowerCase("es"));if(duplicate){setMessage(`${name} ya existe como ingrediente`);return}
    const stockChanged=Math.abs(stock-product.stock)>.000001;if(stockChanged&&!stockReason){setMessage("Escribe el motivo si vas a cambiar el stock");return}
    const productBefore={...product},previousStock=product.stock;product.name=name;product.cost=cost;const editable=asInventoryProduct(product);editable.stockUnit=unit;editable.lowStockThreshold=threshold;
    if(stockChanged){const delta=Number((stock-previousStock).toFixed(4)),now=new Date().toISOString(),movementId=makeId("stock");product.stock=Number(stock.toFixed(4));const productAfter={...product},movement:StockMovementRecord={id:movementId,tenantId:workspace.tenantId,branchId:workspace.branchId,productId:product.id,type:delta>0?"adjustment_in":"adjustment_out",quantity:delta,previousStock,newStock:product.stock,reference:stockReason,clientOperationId:movementId,createdAt:now};next.stockMovements.unshift(movement);enqueueInventoryAdjustment(next,{productId:product.id,delta,reason:stockReason,movementId,createdAt:now,productBefore,productAfter,movement});saveLocalDatabase(next,{trackChanges:false});setDb(loadLocalDatabase());setMessage(`${name} actualizado · stock ${formatStock(product.stock,unit)}`);window.dispatchEvent(new CustomEvent(KIUBO_DATA_REFRESHED,{detail:{source:"inventory-edit"}}))}else persist(next,`${name} actualizado`);
    setEditIngredientId("");
  };
  const addRecipeComponent='''
t,n=re.subn(pattern,replacement,t,count=1,flags=re.S);assert n==1,'inventory update function'
old='<form className={styles.editForm} onSubmit={e=>updateIngredient(e,product.id)}><div className={styles.formRow}><input name="name" defaultValue={product.name} placeholder="Nombre" required/><input name="unit" defaultValue={stockUnit(product)} placeholder="Unidad" required/></div><div className={styles.formRow}><input name="cost" type="number" min="0" step="0.01" defaultValue={product.cost} placeholder="Costo"/><input name="threshold" type="number" min="0" step={quantityStep} defaultValue={lowStockThreshold(product)} placeholder="Mínimo"/></div><div className={styles.editActions}><a href="#inventory-adjustment">Cambiar stock</a><button type="submit">Guardar cambios</button></div></form>'
